variants.code_sketch:
let task = Task {
    try await withTaskCancellationHandler {
        for await chunk in stream {                 // cooperative await points
            try Task.checkCancellation()
            try await process(chunk)
        }
    } onCancel: {
        cancelUnderlyingOperation()                 // runs immediately on cancel()
    }
}
task.cancel()                                       // request, not termination

